import subprocess, collections, re

def show(ref):
    text = subprocess.check_output(["git","show",f"{ref}:intake/log.md"], text=True)
    rows = []
    outside = []
    in_table = False
    header_cols = None
    for i,line in enumerate(text.splitlines(),1):
        if line.startswith("| ID |"):
            in_table = True
            header_cols = line.count("|") - 1
            continue
        if line.startswith("|----"):
            continue
        if in_table and line.startswith("|"):
            cols = [c.strip() for c in line.strip().strip("|").split("|")]
            rows.append((i, cols[0], len(cols), line))
        elif in_table and line.startswith("|") is False and line.strip()=="":
            continue
        elif in_table and not line.startswith("|"):
            # table ended
            in_table = False
        if (not in_table) and line.startswith("| GB-") or (not in_table and line.startswith("| PR") or (not in_table and line.startswith("| O"))):
            outside.append((i, line[:80]))
    ids = [r[1] for r in rows]
    dup = [i for i,c in collections.Counter(ids).items() if c>1]
    bad = [(i,id_,n) for i,id_,n,_ in rows if n!=12]
    print(f"=== {ref} ===")
    print(f"header_cols={header_cols} table_rows={len(rows)} bad_col_rows={len(bad)} duplicate_ids={dup or 'none'} outside_table_pipe_rows={len(outside)}")
    if bad:
        for b in bad[:10]:
            print(" BAD", b)
    if outside:
        for o in outside:
            print(" OUT", o)
    print(" last ids", ids[-8:])
    # GB-063 occurrences
    n063 = len(re.findall(r"GB-063", text))
    n065 = len(re.findall(r"GB-065", text))
    print(f" GB-063 count={n063} GB-065 count={n065}")

show("origin/main")
show("origin/desk/gb-063-hyb-011")

# titles containing GB-063 on the branch diff files
print("--- GB-063 in branch tip files ---")
for path in ["intake/log.md","merge/HYB-011-EXCLUSION-MANIFEST.md","merge/HYB-015-GITBOOKAI-RULES.md","mesh/LANE-HANDOFF-2026-10-12.md"]:
    try:
        text = subprocess.check_output(["git","show",f"origin/desk/gb-063-hyb-011:{path}"], text=True)
    except subprocess.CalledProcessError:
        print(path, "missing")
        continue
    for i,line in enumerate(text.splitlines(),1):
        if "GB-063" in line or "gb-063" in line:
            print(f"{path}:{i}: {line[:160]}")
