import collections, subprocess
def measure(label, text):
    rows=[]; in_table=False; outside=0; header=None
    for line in text.splitlines():
        if line.startswith("| ID |"):
            in_table=True; header=line.count("|")-1; continue
        if line.startswith("|----"):
            continue
        if in_table and line.startswith("|"):
            cols=[c.strip() for c in line.strip().strip("|").split("|")]
            rows.append((cols[0], len(cols)))
        elif in_table and line.strip() and not line.startswith("|"):
            in_table=False
        if (not in_table) and line.startswith("|"):
            outside += 1
    ids=[r[0] for r in rows]
    # also count GB-063 id tokens in pipe rows whether in or out of table
    id_tokens=[]
    for line in text.splitlines():
        if line.startswith("|") and not line.startswith("|----") and not line.startswith("| ID"):
            cell=line.strip().strip("|").split("|")[0].strip()
            id_tokens.append(cell)
    dups=sorted(i for i,c in collections.Counter(id_tokens).items() if c>1)
    bad=sum(1 for _,n in rows if n!=12)
    print(f"{label}: header={header} in_table={len(rows)} bad_in_table={bad} outside={outside} id_dups={dups or 'none'} gb063={id_tokens.count('GB-063')} gb065={id_tokens.count('GB-065')} id_rows={len(id_tokens)}")

measure("naive-rebase e544a4c", subprocess.check_output(["git","show","e544a4c:intake/log.md"], text=True))
